/* Items-backed workflow authoring and local executable definitions. */
const v1Render=render,v1Inspect=inspect,v1Validate=validateWorkflow,v1Editor=renderEditor,v1SimInput=simInput,v1SimAnswer=simAnswer,v1Common=commonView;
function allWorkflowDrafts(){return [...Object.entries(state.sops||{}),...Object.entries(state.archivedSops||{}).flatMap(([m,list])=>(list||[]).map(s=>[m,s]))];}
function migrateItemReferences(){for(const [,s] of allWorkflowDrafts()){for(const graph of [s,s.published,...(s.versions||[])].filter(Boolean)){for(const n of graph.nodes||[]){if(n.action==='Select medicine'){n.action='Use configured item';n.itemId=n.itemId||(n.medicine==='Vet-approved treatment B'?'item-treatment-b':'item-treatment-a');delete n.medicine;}if(n.answer==='Catalogue')n.catalogModule??='Health';}}}persist();}
function itemPath(item){if(!item)return 'Unavailable item';const cats=state.itemCategories||[];return [item.module,cats.find(c=>c.id===item.categoryId)?.name,cats.find(c=>c.id===item.subcategoryId)?.name].filter(Boolean).join(' › ');}
function nodeCatalogue(n,m=current){return availableItems(m).filter(i=>!n.catalogModule||i.module===n.catalogModule);}
function selectConfiguredItem(id){if(!canEdit())return;const n=sop().nodes.find(x=>x.id===selected);n.itemId=id;persist();drawGraph();inspect();}
function showItemReference(id){const i=itemById(id);if(!i)return toast('This item no longer exists.');modal(i.name,`<div class="eyebrow">${esc(itemPath(i))}</div><span class="badge">${i.active?'Active':'Archived'} · revision ${i.revision||1}</span><h3 style="margin-top:20px">Description</h3><p>${esc(i.description)}</p><h3>Purpose / use</h3><p>${esc(i.purpose)}</p><div class="linkline"><span>Unit</span><b>${esc(i.unit)}</b></div>`);}
render=function(){v1Render();const nav=$('#nav');if(nav)nav.insertAdjacentHTML('afterbegin',`<button class="${current==='Items'?'active':''} registry-nav" onclick="go('Items')"><span>▦</span>Items Config</button>`);if(current==='Items')renderItems();};
const previousCloseModal=closeModal;
closeModal=function(){previousCloseModal();if(current==='Items')renderItems();};
const oldGraph=drawGraph;
drawGraph=function(){oldGraph();for(const n of sop().nodes){if(n.type==='action'&&n.action==='Use configured item'){const el=document.querySelector('[data-node="'+n.id+'"] .nmeta');if(el)el.textContent=itemById(n.itemId)?.name||'Choose configured item';}if(n.type==='condition'){const q=sop().nodes.find(x=>x.id===n.source);if(q?.answer==='Catalogue'){const el=document.querySelector('[data-node="'+n.id+'"] .nmeta');if(el)el.textContent=n.op+' '+(itemById(n.value)?.name||'Choose item');}}}};
const oldGo=go;
go=function(m,t){current=m;tab=t||(m==='Items'?'Registry':m==='Common'?'Sharing':'Configuration');selected='q1';if(typeof window!=='undefined'&&window.history)window.history.replaceState(null,'','#'+encodeURIComponent(m)+'/'+encodeURIComponent(tab));render();};
resourcesFor=function(m){return [...(state.shared.photo.includes(m)?['Common · Photo evidence']:[]),...(state.shared.temperature.includes(m)?['Common · Temperature question']:[]),`${availableItems(m).length} active configured items available`,...(state.shared.approval.includes(m)?['Common · Request approval']:[])];};
inspect=function(){const n=sop().nodes.find(x=>x.id===selected);if(!n)return;v1Inspect();const panel=$('#inspector'),dis=!canEdit()?'disabled':'';
  if(n.type==='action'){
    const allowed=['Instruction',...(state.shared.approval.includes(current)?['Request approval']:[]),'Create follow-up','Use configured item','Use shared resource',...(state.customLibrary||[]).filter(x=>x.action&&!x.draft&&(!x.modules||x.modules.includes(current))).map(x=>x.name)];
    const options=availableItems(current),i=itemById(n.itemId);
    panel.innerHTML=`<div class="cardheader"><h2>Action settings</h2><span class="badge purple">Action</span></div><label class="field"><span>Operator prompt</span><input aria-label="Step title" value="${esc(n.label)}" oninput="editNode('label',this.value)" ${dis}></label><label class="field"><span>Action type</span><select aria-label="Action type" onchange="editNode('action',this.value,true)" ${dis}>${!allowed.includes(n.action)?`<option selected disabled>${esc(n.action)} · unavailable</option>`:''}${allowed.map(a=>`<option ${n.action===a?'selected':''}>${esc(a)}</option>`).join('')}</select></label>${n.action==='Use configured item'?`<label class="field"><span>Configured item</span><select aria-label="Configured item" onchange="selectConfiguredItem(this.value)" ${dis}><option value="">Choose an item…</option>${i&&!options.some(x=>x.id===i.id)?`<option value="${i.id}" selected disabled>${esc(i.name)} · unavailable</option>`:''}${options.map(x=>`<option value="${x.id}" ${x.id===n.itemId?'selected':''}>${esc(x.name)} — ${esc(x.module)}</option>`).join('')}</select></label>${i?`<div class="item-reference"><div class="eyebrow">${esc(itemPath(i))}</div><b>${esc(i.name)}</b><p>${esc(i.purpose)}</p><span class="muted">${esc(i.unit)} · revision ${i.revision||1}</span></div>`:'<p class="muted">Create items once in Items Config, then share them with this module.</p>'}<div class="hint">Item selection identifies what to use. Authorised treatment or stock operations remain separate module actions.</div>`:''}<label class="field"><span>Operator instruction</span><textarea aria-label="Action instruction" oninput="editNode('instruction',this.value)" ${dis}>${esc(n.instruction||'Follow the approved procedure and record the outcome.')}</textarea></label><label class="field"><span>Continue to</span>${destination(n.next,'next')}</label><div class="actions"><button class="danger" onclick="deleteNode()" ${dis}>Delete step</button></div><p class="hint">Draft edits save locally. Publish creates an immutable definition.</p>`;
  }else if(n.type==='condition'){
    const source=panel.querySelector('[aria-label="Decision source"]');if(source)source.setAttribute('onchange',"editNode('source',this.value,true)");
    const q=sop().nodes.find(x=>x.id===n.source);
    if(q?.answer==='Catalogue'){
      const values=nodeCatalogue(q),value=panel.querySelector('[aria-label="Decision value"]'),op=panel.querySelector('[aria-label="Decision comparison"]');
      if(value)value.outerHTML=`<select aria-label="Decision value" onchange="editNode('value',this.value)" ${dis}><option value="">Choose item…</option>${n.value&&!values.some(i=>i.id===n.value)?`<option selected disabled value="${esc(n.value)}">Unavailable selection</option>`:''}${values.map(i=>`<option value="${i.id}" ${n.value===i.id?'selected':''}>${esc(i.name)}</option>`).join('')}</select>`;
      if(op)op.innerHTML=`${!['=','!='].includes(n.op)?'<option selected disabled>Choose comparison…</option>':''}${['=','!='].map(o=>`<option ${n.op===o?'selected':''}>${o}</option>`).join('')}`;
    }
  }else if(n.type==='question'){
    const sel=panel.querySelector('select[aria-label="Answer type"]');if(sel&&!Array.from(sel.options).some(o=>o.value==='Catalogue'))sel.insertAdjacentHTML('beforeend','<option>Catalogue</option>');
    if(n.answer==='Catalogue'){if(sel)sel.value='Catalogue';panel.insertAdjacentHTML('beforeend',`<div class="catalogue-config"><label class="field"><span>Item source</span><select aria-label="Item source" onchange="editNode('catalogModule',this.value,true)"><option value="">All shared items</option>${modules.map(m=>`<option ${n.catalogModule===m?'selected':''}>${m}</option>`).join('')}</select></label><p class="muted">${nodeCatalogue(n).length} active items currently available. Operators select from the published item snapshot.</p></div>`);}
  }
};
validateWorkflow=function(s,m=current){const normalized=structuredClone(s);for(const n of normalized.nodes){if(n.action==='Use configured item')n.action='Instruction';if(n.answer==='Catalogue')n.answer='Text';}const errors=v1Validate(normalized,m);for(const n of s.nodes){if(n.type==='condition'){const q=s.nodes.find(x=>x.id===n.source);if(q?.answer==='Catalogue'&&(!['=','!='].includes(n.op)||!nodeCatalogue(q,m).some(i=>i.id===n.value)))errors.push(n.label+': choose an available catalogue item and an equals or not-equals comparison.');}if(n.type==='action'&&n.action==='Use configured item'){const i=itemById(n.itemId);if(!i)errors.push(n.label+': choose a configured item.');else if(!i.active)errors.push(n.label+': '+i.name+' is archived.');else if(!availableItems(m).some(x=>x.id===i.id))errors.push(n.label+': '+i.name+' is not shared with '+m+'.');}if(n.type==='question'&&n.answer==='Catalogue'&&!nodeCatalogue(n,m).length)errors.push(n.label+': no active items are available from this source.');if(n.type==='question'&&n.answer==='Number'&&!n.unit)errors.push(n.label+': choose a measurement unit.');if(n.type==='question'&&['Single choice','Multiple choice'].includes(n.answer)){const choices=(n.choices||'Good, Needs attention').split(',').map(x=>x.trim());if(choices.some(x=>!x)||new Set(choices).size!==choices.length)errors.push(n.label+': choices must be non-empty and unique.');}}return [...new Set(errors)];};
function compileWorkflow(s,m=current,version=s.version||0){const errors=validateWorkflow(s,m);if(errors.length){const e=new Error(errors.join('\n'));e.validationErrors=errors;throw e;}const nodes=structuredClone(s.nodes),items={},catalogues={};for(const n of nodes){delete n.x;delete n.y;if(n.type==='action'&&n.action==='Use configured item')items[n.itemId]=structuredClone(itemById(n.itemId));if(n.type==='question'&&n.answer==='Catalogue')catalogues[n.id]=structuredClone(nodeCatalogue(n,m));}return {schema:'mesha.workflow.preview.v1',module:m,title:s.title,version,entryNodeId:nodes.find(n=>n.type==='start').next,nodes,items,catalogues,config:{sales:structuredClone(state.sales)}};}
function definitionDialog(){try{window.previewDefinition=compileWorkflow(sop(),current,sop().version+1);const d=window.previewDefinition;modal('Workflow definition',`<p>This is the draft workflow definition for review. The live Android app does not consume it yet.</p><div class="definition-stats"><span>${d.nodes.length} steps</span><span>${Object.keys(d.items).length} item references</span><span>v${d.version}</span></div><pre class="definition-code">${esc(JSON.stringify(d,null,2))}</pre><div class="actions"><button class="primary" onclick="downloadDefinition()">Download JSON</button></div>`,true);}catch(e){validateDialog();}}
function downloadDefinition(){const d=window.previewDefinition;if(!d)return;const blob=new Blob([JSON.stringify(d,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='mesha-workflow-v'+d.version+'.json';a.click();URL.revokeObjectURL(url);toast('Workflow definition downloaded.');}
renderEditor=function(){v1Editor();const toolbar=document.querySelector('.toolbar');if(toolbar&&canEdit())toolbar.insertAdjacentHTML('beforeend','<button onclick="definitionDialog()">Definition & export</button>');};
confirmPublish=function(){if(!canEdit())return;const s=sop();let definition;try{definition=compileWorkflow(s,current,s.version+1);}catch(e){return validateDialog();}if(s.published)(s.versions??=[]).push(structuredClone(s.published));s.version++;s.published={nodes:structuredClone(s.nodes),title:s.title,version:s.version,definition};record('Published '+s.title+' v'+s.version+' with pinned item references');closeModal();renderEditor();toast('Published locally. Item details are pinned to this workflow version.');};
startSim=function(){const s=sop();let definition;try{if(canEdit())definition=compileWorkflow(s,current,s.version||0);else {if(!s.published)return toast('No published workflow for this role.');definition=s.published.definition||compileWorkflow(s.published,current,s.published.version);}}catch(e){if(canEdit())return validateDialog();return toast('This older publication needs a new validated definition.');}definition=structuredClone(definition);sim={definition,nodes:definition.nodes,id:definition.entryNodeId,answers:{},path:[],title:definition.title,mode:canEdit()?'Draft definition':'Published v'+definition.version};renderSim();};
simInput=function(n){if(n.answer!=='Catalogue')return v1SimInput(n);const list=sim.definition.catalogues[n.id]||[];return `<select id="simvalue" aria-label="Operator answer"><option value="">Select an item…</option>${list.map(i=>`<option value="${i.id}">${esc(i.name)} — ${esc(i.module)}</option>`).join('')}</select><p class="hint">${list.length} configured items · published catalogue snapshot</p>`;};
simAnswer=function(){const n=sim.nodes.find(n=>n.id===sim.id);if(n.answer!=='Catalogue')return v1SimAnswer();const id=$('#simvalue').value,i=(sim.definition.catalogues[n.id]||[]).find(x=>x.id===id);if(!i){$('#simerror').textContent='Select an available item.';return;}sim.answers[n.id]=id;sim.path.push(n.label+': '+i.name);sim.id=n.next;renderSim();};
renderSim=function(){const n=sim.nodes.find(n=>n.id===sim.id);if(!n)return;if(n.type==='condition'){const a=sim.answers[n.source],match=compare(a,n.op,n.value);sim.path.push(`${n.label}: ${a} ${n.op} ${n.value} → ${match?'Match':'Otherwise'}`);sim.id=match?n.yes:n.no;return renderSim();}const item=n.itemId?sim.definition.items[n.itemId]:null;const body=n.type==='end'?`<span class="badge">Complete</span><h2>${esc(n.label)}</h2><p>Outcome recorded in this test only.</p>`:n.type==='action'?`<span class="badge purple">Action</span><h2>${esc(n.label)}</h2><p>${esc(n.instruction||'Follow the approved procedure.')}</p>${item?`<div class="item-reference"><span class="eyebrow">${esc(item.module)} · item revision ${item.revision||1}</span><h3>${esc(item.name)}</h3><p>${esc(item.purpose)}</p><span class="muted">${esc(item.unit)} · pinned definition</span></div>`:`<div class="notice">${esc(n.action)} · simulated only</div>`}<button class="primary" onclick="simAdvance()">Acknowledge & continue</button>`:`<span class="badge blue">Required question</span><h2>${esc(n.label)}</h2>${simInput(n)}<div id="simerror" class="error hint"></div><button class="primary" onclick="simAnswer()">Continue →</button>`;$('#overlay').innerHTML=`<div class="modalbg"><section class="modal wide"><div class="modalhead"><div><h2>Operator preview</h2><span class="muted">${esc(sim.mode)} · ${esc(sim.title)} · No live actions</span></div><button onclick="closeModal()" aria-label="Close operator preview">✕</button></div><div class="two simlayout"><div class="phone"><span class="muted">Mesha · ${esc(sim.definition.module)}</span><div class="progress"><span style="width:${n.type==='end'?100:Math.min(90,(sim.path.length+1)*20)}%"></span></div>${body}</div><div><h3>Path taken</h3><div class="timeline">${sim.path.map(p=>`<div class="muted">${esc(p)}</div>`).join('')||'<p>Answer a question to see its next step.</p>'}</div><button onclick="startSim()">↻ Restart test</button><div class="hint">This run keeps its item and rule snapshots even if a draft changes.</div></div></div></section></div>`;};
function setItemSharing(id,m,on){if(!canEdit())return;const i=itemById(id);if(!i||m===i.module)return;const refs=itemUsages(id).filter(u=>u.module===m);if(!on&&refs.length){modal('Remove item access?',`<p>${esc(i.name)} is referenced by ${refs.length} ${esc(m)} workflow(s). Their drafts will need attention. Existing published definitions retain their item snapshot.</p><button class="danger" onclick="applyItemSharing('${id}','${m}',false);closeModal();render()">Remove access</button>`);return;}applyItemSharing(id,m,on);}
function applyItemSharing(id,m,on){if(!canEdit())return;const i=itemById(id);if(!i||m===i.module)return;i.shares=(i.shares||[]).filter(x=>x!==m);if(on)i.shares.push(m);i.revision=(i.revision||1)+1;record((on?'Shared ':'Removed access to ')+i.name+' · '+m);render();}
commonView=function(){if(tab!=='Sharing')return v1Common();$('#content').innerHTML=`<div class="heading"><div><h2>Shared items & building blocks</h2><p>Items stay owned by their source vertical. Enable the modules that can select each item.</p></div><button onclick="go('Items')">Reusable item library</button></div><section class="card"><div class="tablewrap"><table><thead><tr><th>Configured item / owner</th>${modules.map(m=>`<th>${m==='Preventive Care'?'Vaccination':m}</th>`).join('')}</tr></thead><tbody>${state.items.filter(i=>i.active).map(i=>`<tr><td><button class="textbutton" onclick="showItemReference('${i.id}')">${esc(i.name)}</button><div class="hint">${esc(itemPath(i))}</div></td>${modules.map(m=>`<td><input type="checkbox" aria-label="Share ${esc(i.name)} with ${m}" ${i.module===m||i.shares.includes(m)?'checked':''} ${i.module===m||!canEdit()?'disabled':''} onchange="setItemSharing('${i.id}','${m}',this.checked)"></td>`).join('')}</tr>`).join('')}</tbody></table></div></section><section class="card"><h2>Shared questions & actions</h2><p>Definitions are reusable; each SOP owns its next steps.</p><div class="tablewrap"><table><thead><tr><th>Building block</th>${modules.map(m=>`<th>${m==='Preventive Care'?'Vaccination':m}</th>`).join('')}</tr></thead><tbody>${[['temperature','Temperature measurement'],['photo','Photo evidence'],['approval','Request approval']].map(([key,name])=>`<tr><td>${name}</td>${modules.map(m=>`<td><input type="checkbox" aria-label="Share ${name} with ${m}" ${state.shared[key].includes(m)?'checked':''} ${!canEdit()?'disabled':''} onchange="share('${key}','${m}',this.checked)"></td>`).join('')}</tr>`).join('')}</tbody></table></div></section><div class="two"><section class="card"><span class="badge blue">Required dependency</span><h2>Sales → Weighing</h2><p>Eligibility ${esc(state.sales.comparison)} ${state.sales.weight-state.sales.margin} kg · ₹${state.sales.rate}/kg. One published Sales policy powers both screens.</p><button onclick="go('Sales')">Sales policy</button></section><section class="card"><h2>Try an item-backed workflow</h2><p>Create or edit an item, share it with Procurement, then choose it in a workflow action.</p><button class="primary" onclick="go('Procurement','Editor')">Procurement workflow</button></section></div>`;};
function bootStudioV2(){ensureItemState();migrateItemReferences();const hash=decodeURIComponent(window.location.hash.slice(1)).split('/');current=hash[0]&&(['Items','Common',...modules].includes(hash[0]))?hash[0]:'Items';tab=hash[1]||(current==='Items'?'Registry':'Configuration');render();}
if(typeof window!=='undefined')window.addEventListener('DOMContentLoaded',bootStudioV2);
if(typeof globalThis!=='undefined')Object.assign(globalThis,{startSim,renderSim,simAnswer,simAdvance,definitionDialog,downloadDefinition});
if(typeof exposeGlobals==='function')exposeGlobals();
